{
  "technical_and_design_decisions": [
    "Use Spring Boot and Spring MVC for REST APIs (U3).",
    "Use Spring Batch for batch job implementation (U6).",
    "Use Spring Security for GF authentication (U5).",
    "Adopt standard Maven project structure and existing code patterns.",
    "For U4, create a new Boot-based ModuleRunner class and auto-configuration.",
    "For U8, relocate the reactor module into core package with minimal API changes.",
    "For U1, use external configuration properties to specify metastore database."
  ],
  "assumptions": [
    "Development is performed by a singe developer.",
    "Existing codebase is accessible and well-understood.",
    "Documentation is written in AsciiDoc and included in the project.",
    "Testing includes unit tests and integration tests for each feature.",
    "No external dependeies beyond existing Spring ecosystem.",
    "All user stories are independent and can be implemented sequentially.",
    "Effort estimates are in work-hours and assume no interruptions."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Implement Sqoop metastore customization (U1)",
      "activity_description": "Add configuration option to change default Sqoop metastore; modify metastore setup logic; update configuration properties; write tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A2",
      "activity_name": "Write documentation for HDFS-backed module registry (U2)",
      "activity_description": "Create or update AsciiDoc documentation describing how to configure the HDFS backed module registry as per XD-2287.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A3",
      "activity_name": "Implement REST API for all metrics (U3)",
      "activity_description": "Design and implement new endpoints /metrics/counters/all, /metrics/gauges/all, /metrics/rich-gauges/all; add corresponding service methods; write tests.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "Implement Boot-based ModuleRunner (U4)",
      "activity_description": "Create a Spring Boot application class ModuleRunner that starts the XD module without traditional container; add auto-configuration; ensure compatibility; write tests.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A5",
      "activity_name": "Implement GF source with native authentication (U5)",
      "activity_description": "Modify the GF source to support native authentication; add configuration properies for security; write corresponding documentation; write tests.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A6",
      "activity_name": "Implement jdbcgpfdist batch job (U6)",
      "activity_description": "Create batch job that reads from JDBC and writes to HAWQ/GPDB via gpfdist; reuse existing gpfdist sink; configure job parameters; write tests.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A7",
      "activity_name": "Separate mocks from real repository in tests (U7)",
      "activity_description": "Refactor test infrastructure to remove coupling between mocks and real repostories; create thin abstraction layer; update all affected tests.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A8",
      "activity_name": "Move reactor-based data processor module to core (U8)",
      "activity_description": "Relocate the spring-xd-reactor module from external repo into core package; update imports and dependencies; ensure compatibility; write tests.",
      "most_likely_effort": 20
    }
  ],
  "reported_total": {
    "most_likely_effort": 168
  }
}

